        let score: Score = try importer.readScore()
        score.stylesheet.barNumberDisplay = display
        return score
    }

    public static func barsTex(_ staffTex: String = "") -> String {
        var tex: String = staffTex
        do {
            var i: Double = 0.0
            while i < 24 {
                tex += ":4 c4 d4 e4 f4 |"
                i += 1
            }
        }
        return tex
    }

    /**
     * Collects the bar numbers which take part in the placement (have an x-range), per visible staff.
     */
    public static func collectBarNumbers(_ api: AlphaTabApiBase<Any?>) throws -> List<StaffBarNumbers> {
