        let inner: ScoreRenderer = ((wrapper.instance as Any?) as! ScoreRenderer)
        let result: List<StaffBarNumbers> = List<StaffBarNumbers>()
        let range: EffectBandXRange = EffectBandXRange(xStart: 0.0, xEnd: 0.0)
        for system in try jsNonNull(inner.layout).systems {
            for group in system.staves {
                for staff in group.staves {
                    if !staff.isVisible {
                        continue
