                    let barIndices: List<Double> = List<Double>()
                    for renderer in staff.barRenderers {
                        let isShown: Bool = try renderer.topEffects.bands.some({ (b: EffectBand) -> Bool in
                            return try b.info.effectId == "BarNumber" && b.computeLocalXRange(range)
                        })
                        if isShown {
                            barIndices.push(renderer.bar.index)
                        }
